        for i in range(len(items)):
            factor = items[i][0]

            for j in range(len(items)):
                other_factor = items[j][0]

                if i != j and other_factor % factor == 0:
                    rewards[i] += 1

        def dfs(i, remaining, is_reward_available):
            if i == len(items) or remaining == 0:
                return 0

            key = (i, remaining, is_reward_available)

            if key in memo:
                return memo[key]

