            # Skip and move to the next item.
            skip = dfs(i + 1, remaining, True)

            take = 0

            if remaining >= price:
                value = 1

                if is_reward_available:
                    value += rewards[i]

                take = value + dfs(i, remaining - price, False)

            result = max(skip, take)
            memo[key] = result
